#!/usr/bin/env bash
# The sounds are generated by tools/sound/build.mjs, committed, and must match the script.
set -uo pipefail
root="$(cd "$(dirname "$0")/../.." && pwd)"
fail=0
check() { if eval "$2"; then echo "ok   $1"; else echo "FAIL $1: $2" >&2; fail=1; fi; }

node "$root/tools/sound/build.mjs" > /dev/null
check test_build_is_reproducible 'git -C "$root" diff --quiet -- src/sound && [ -z "$(git -C "$root" ls-files --others --exclude-standard -- src/sound)" ]'

report="$(node -e '
const fs = require("fs");
const dir = process.argv[1];
for (const name of ["place", "note", "clash", "hint", "undo", "win", "music"]) {
  const f = `${dir}/${name}.wav`;
  if (!fs.existsSync(f)) { console.log(`${name} missing`); continue; }
  const b = fs.readFileSync(f);
  const n = b.readUInt32LE(40) / 2, rate = b.readUInt32LE(24);
  let peak = 0;
  for (let i = 0; i < n; i++) peak = Math.max(peak, Math.abs(b.readInt16LE(44 + 2 * i)) / 32768);
  console.log(name, (n / rate).toFixed(2), peak.toFixed(3), b.readInt16LE(44), b.readInt16LE(44 + 2 * (n - 1)));
}' "$root/src/sound")"
echo "$report" | sed 's/^/     /'
check test_all_seven_exist '! echo "$report" | grep -q missing'
check test_effects_are_short 'echo "$report" | awk '\''$1 != "music" && $2 > 1.5 { bad = 1 } END { exit bad }'\'''
check test_music_is_16_seconds 'echo "$report" | awk '\''$1 == "music" && ($2 < 15.9 || $2 > 16.1) { bad = 1 } END { exit bad }'\'''
check test_peaks_at_most_0_8 'echo "$report" | awk '\''$3 > 0.801 { bad = 1 } END { exit bad }'\'''
check test_effects_start_and_end_silent 'echo "$report" | awk '\''$1 != "music" && ($4 != 0 || $5 != 0) { bad = 1 } END { exit bad }'\'''
exit "$fail"
